from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    singles = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            for y, x in q:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if len(q) == 1:
                singles.append((r, c))
    out = [row[:] for row in grid]
    global_counts = Counter(value for row in grid for value in row)
    background = global_counts.most_common(1)[0][0]
    for r, c in singles:
        neighbors = [grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= y < h and 0 <= x < w]
        if neighbors:
            counts = Counter(neighbors)
            best = max(counts.values())
            candidates = [color for color, count in counts.items() if count == best]
            if background in candidates and len(candidates) > 1:
                candidates.remove(background)
            out[r][c] = max(candidates, key=lambda color: global_counts[color])
    return out

